insert into ai_agent_tool (id, agent_id, tool_code, decision, remark, create_dept, create_by, create_time) values (1761400000000020356, 1761400000000020305, 'search_knowledge_base', '0', '只读：知识库检索', 1761000000000000103, 1761100000000000001, now()) on conflict (agent_id, tool_code) do nothing;
insert into ai_skill (id, name, description, skill_content, source, metadata_json, created_at, updated_at, owner_dept_id, visible_scope, status, remark, create_dept, create_by, update_by) values (1761400000000020501, 'platform_daily_digest', '平台运行日报：汇总某天五块运行数据，按阈值判异动并输出人话日报', '# 平台运行日报 ## 何时使用 定时任务（每日 08:00）触发时，或用户问「昨天平台运行怎么样」「有没有异常」。 ## 步骤 1. 调用 platform_daily_digest 取昨日五块数据（**只调一次**，不传日期即昨天） 2. 判异动，按阈值定级（**只用当日值，不做跨日比较**）： - 定时任务失败数 > 0 → 需处理 - 登录失败 > 20 次 → 异常 - 登录有新 IP（异动数 > 0）→ 需关注 - 配额使用率 > 80% → 需关注（配额为 null 表示不限，不显示使用率） - 权限决策中「需确认 + 拒绝」合计 ≥ 5 次 → 需关注 3. 按模板输出人话日报：**没有数据的块写「无数据」**，不要写成 0，也不要推测原因 4. **正文第一行必须写明结论级别**，格式固定为「结论级别：平稳」/「结论级别：需关注」/「结论级别：需处理」 ## 输出模板 结论级别：平稳|需关注|需处理 ### 平台运行日报（YYYY-MM-DD） - 用量：总 Token X（环比 ±Y%）、请求 N 次、工具 M 次；配额使用率 Z% - 任务：执行 A 次，成功 B，失败 C（失败任务：…） - 待办：积压 D 条（最多节点：…，最久滞留 … 分钟）——注意这是**当前快照**，不是当日历史 - 权限：允许 E / 需确认 F / 拒绝 G - 登录：成功 H，失败 I；新 IP J 个 - 一句话结论 ## 纪律 - 所有数字**必须引用工具返回的原值**，不得估算、换算或加工 - **不推测异动原因**：可以写「建议人工排查」，不许编造可能原因 - 无数据的块**如实写「无数据」** - 只输出日报本身；**不要尝试修改平台状态**（除日报落库外没有任何写权限） - **输出日报正文后必须调用 `write_daily_digest` 落库**（只写日报表，按日期覆盖更新；不传 date 即昨日） - **不要输出任何前言 / 开场白**（不要写英文说明或客套话）；**正文第一行就是「结论级别：X」** - 正文首行的结论级别格式不得改动（系统据此落库）', 'agenthub', null, now(), now(), null, '0', '0', '内置技能：配合智能体 platform_ops 与定时任务生成每日运行日报', 1761000000000000103, 1761100000000000001, 1761100000000000001) on conflict do nothing;
insert into ai_expert_agent (id, agent_name, agent_code, description, sys_prompt, model_id, memory_model_id, summary_model_id, subagent_model_id, daily_token_quota, daily_request_quota, monthly_token_quota, owner_dept_id, visible_scope, max_iters, status, remark, expert_domain, capability_desc, output_contract, expert_write_enabled, auto_route, memory_enabled, create_dept, create_by, create_time, update_by, update_time, del_flag) values (1761400000000020306, '平台运维助手', 'platform_ops', '按技能口径生成平台运行日报（供定时任务使用，也可直接对话追问）', '你是平台运维助手。生成运行日报时严格按技能 platform_daily_digest 的口径执行：先调用 platform_daily_digest 取当日五块数据（只调一次），再判异动并按模板输出；正文第一行写明结论级别。所有数字引用工具返回原值，禁止估算或推测原因；数据为 null 的块如实写「无数据」；待办积压是当前快照，不是当日历史。需要明细时调用 platform_daily_drill；你也可以直接回答用户关于用量的追问。输出日报正文后，必须调用 write_daily_digest 把日报落库（date 取本次统计日期，缺省即昨日）。', 1761400000000020400, null, null, null, 0, 0, 0, 1761000000000000103, '0', 10, '0', '内置专家（演示）：只读工具集（platform_daily_digest / platform_daily_drill / ai_usage_by_agent）+ 写工具 write_daily_digest（允许档）；定时任务直接指定该专家执行', null, '负责平台运行数据的汇总与日报口径：回答「昨天平台运行怎么样」「谁用得最多」「昨天登录失败都是哪些 IP」；按技能 platform_daily_digest 输出日报。不受理公告/机构等业务域（归各自专家）。', null, '1', '1', '0', 1761000000000000103, 1761100000000000001, now(), 1761100000000000001, now(), '0') on conflict do nothing;
insert into ai_agent_skill (id, agent_id, skill_id, remark, create_dept, create_by, create_time, update_by, update_time) values (1761400000000020502, 1761400000000020306, 1761400000000020501, '平台运维助手绑定「平台运行日报」技能', 1761000000000000103, 1761100000000000001, now(), 1761100000000000001, now()) on conflict do nothing;
