insert into ai_agent_tool (id, agent_id, tool_code, remark, create_dept, create_by, create_time, update_by, update_time, decision) values (1761400000000020505, 1761400000000020306, 'ai_usage_by_agent', '按智能体用量（只读）', 1761000000000000103, 1761100000000000001, now(), 1761100000000000001, now(), '0') on conflict do nothing;
insert into ai_agent_tool (id, agent_id, tool_code, remark, create_dept, create_by, create_time, update_by, update_time, decision) values (1761400000000020506, 1761400000000020306, 'write_daily_digest', '写入日报（落库，允许）', 1761000000000000103, 1761100000000000001, now(), 1761100000000000001, now(), '0') on conflict do nothing;
insert into ai_agent_task (id, task_name, agent_id, agent_code, task_prompt, cron_expression, run_as_user_id, run_as_dept_id, last_run_time, status, remark, create_dept, create_by, create_time, update_by, update_time, del_flag) values (1761400000000020601, '平台运行日报（每日 08:00）', 1761400000000020306, 'platform_ops', '执行昨日平台运行日报：调用 platform_daily_digest 取五块数据，按技能口径判异动并按模板输出，正文首行写明结论级别；数据为 null 的块如实写「无数据」；最后必须调用 write_daily_digest 把日报落库（date 取昨日）。', '0 0 8 * * ?', 1761100000000000001, 1761000000000000103, null, '0', '内置定时任务：每日 08:00 以 admin 身份生成平台运行日报（运行身份决定可见范围）', 1761000000000000103, 1761100000000000001, now(), 1761100000000000001, now(), '0') on conflict do nothing;
